import{_ as o,o as t,c as d,ag as c}from"./chunks/framework.BaNuf0sO.js";const u=JSON.parse('{"title":"app-layout（应用布局族）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/core/src/components/app-layout/README.md","filePath":"docs/core/src/components/app-layout/README.md"}'),a={name:"docs/core/src/components/app-layout/README.md"};function p(r,e,s,l,n,i){return t(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="app-layout-应用布局族" tabindex="-1">app-layout（应用布局族） <a class="header-anchor" href="#app-layout-应用布局族" aria-label="Permalink to &quot;app-layout（应用布局族）&quot;">​</a></h1><blockquote><p>应用壳族：AppLayout 数据桥/机制 + AppPage 页面容器 + AppBody 内容主体 + 六件布局积木（Header/Sidebar/Aside/Breadcrumb/Footer/Theme）。 范式页：<code>apps/reference/src/App.vue</code>（族总装配）、<code>apps/reference/src/pages/app-layout/shell/</code>（自供 shell 积木直引）、<code>apps/reference/src/pages/app-layout/page-slots/</code>（AppPage 四向悬浮槽）、<code>apps/reference/src/pages/app-layout/layout/</code>（布局显隐变体）</p></blockquote><h2 id="组件清单" tabindex="-1">组件清单 <a class="header-anchor" href="#组件清单" aria-label="Permalink to &quot;组件清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>一句话</th><th>核心 props</th><th>文档</th></tr></thead><tbody><tr><td><code>AppLayout</code></td><td>应用布局总控：bridge/appStore/userStore 三注入 + 5 内容锚 + 内置默认经典布局 shell</td><td><code>bridge</code>（必填）<code>appStore</code>（必填）<code>userStore</code>（必填）<code>watermarkContent</code> <code>sidebarAboveHeader</code></td><td><a href="/done-coding-showcase/docs/core/src/components/app-layout/docs/README-AppLayout.html">README-AppLayout.md</a></td></tr><tr><td><code>AppPage</code></td><td>页面主体容器：撑满视口 + 四向悬浮 fixed 插槽 + 超宽屏内容限宽居中</td><td><code>fullViewport</code> <code>fullMode</code> <code>gap</code> <code>contentCentered</code>/<code>contentMaxWidth</code> <code>topBg</code>/<code>bottomBg</code>/<code>leftBg</code>/<code>rightBg</code> <code>nextViewportMaxHeight</code></td><td><a href="/done-coding-showcase/docs/core/src/components/app-layout/docs/README-AppPage.html">README-AppPage.md</a></td></tr><tr><td><code>AppBody</code></td><td>内容主体：内置 RouterView + KeepAlive + 面包屑 affix + #footer 槽</td><td><code>menuFlatList</code></td><td><a href="/done-coding-showcase/docs/core/src/components/app-layout/docs/README-AppBody.html">README-AppBody.md</a></td></tr><tr><td><code>AppHeader</code></td><td>顶栏积木：#left 品牌 + 路由模块菜单（按 path 查 bridge.badge 显徽标）+ #right 操作区</td><td><code>menus</code> <code>menuFlatList</code>（必填）<code>show</code>（未消费）</td><td><a href="/done-coding-showcase/docs/core/src/components/app-layout/docs/README-AppHeader.html">README-AppHeader.md</a></td></tr><tr><td><code>AppSidebar</code></td><td>侧边栏积木：折叠把手 + MenuTree 菜单（树形/分组双形态）+ #top/#bottom 高度自撑</td><td><code>show</code> <code>menus</code>（必填）<code>menuFlatList</code>（必填）<code>aboveHeader</code>；菜单形态读 bridge <code>APP_LAYOUT_SIDEBAR_CONFIG.menuGroupMode</code>（分组态无折叠把手）</td><td><a href="/done-coding-showcase/docs/core/src/components/app-layout/docs/README-AppSidebar.html">README-AppSidebar.md</a></td></tr><tr><td><code>AppAside</code></td><td>右侧补充区积木（对称 AppSidebar），无内置内容</td><td><code>show</code></td><td><a href="/done-coding-showcase/docs/core/src/components/app-layout/docs/README-AppAside.html">README-AppAside.md</a></td></tr><tr><td><code>AppBreadcrumb</code></td><td>面包屑积木：menuFlatList 匹配 route.matched 出链</td><td><code>height</code>（必填）<code>menuFlatList</code>（必填）</td><td><a href="/done-coding-showcase/docs/core/src/components/app-layout/docs/README-AppBreadcrumb.html">README-AppBreadcrumb.md</a></td></tr><tr><td><code>AppFooter</code></td><td>底部状态条积木：高度/样式随 appStore.footerStyle 驱动，零 props</td><td>无</td><td><a href="/done-coding-showcase/docs/core/src/components/app-layout/docs/README-AppFooter.html">README-AppFooter.md</a></td></tr><tr><td><code>AppTheme</code></td><td>主题切换器积木：bridge.theme 直读直写（亮/暗/系统 + 风格下拉）</td><td>无</td><td><a href="/done-coding-showcase/docs/core/src/components/app-layout/docs/README-AppTheme.html">README-AppTheme.md</a></td></tr></tbody></table><h2 id="契约与类型-types-ts" tabindex="-1">契约与类型（types.ts） <a class="header-anchor" href="#契约与类型-types-ts" aria-label="Permalink to &quot;契约与类型（types.ts）&quot;">​</a></h2><p>契约集中在 <code>app-layout/types.ts</code>（族内无每组件独立 types.ts），导出：</p><table tabindex="0"><thead><tr><th>类型</th><th>语义</th></tr></thead><tbody><tr><td><code>AppLayoutAppStoreSlice&lt;UserInfo&gt;</code></td><td>createAppStore 返回类型窄化</td></tr><tr><td><code>AppLayoutUserStoreSlice&lt;UserInfo&gt;</code></td><td>createUserStore 返回类型窄化</td></tr><tr><td><code>AppLayoutBridgeSlice</code></td><td>CoreBridge Pick 窄化：12+ readonly 配置 + theme* 系列 + getRoutes/generateRouteMetaRawTree</td></tr><tr><td><code>AppShellContentAnchor</code></td><td>内容锚名联合：<code>&quot;brand&quot; | &quot;userEntry&quot; | &quot;settings&quot; | &quot;themeSwitcher&quot; | &quot;aside&quot;</code></td></tr><tr><td><code>AppShellProps</code> / <code>AppShellEmits</code>（空）/ <code>AppShellDefaultSlotScope</code>（<code>{ Footer: Component }</code>）/ <code>AppShellAnchorScope</code>（<code>{ Default?: Component }</code>）/ <code>AppShellSlots</code></td><td>布局插件自供 shell 的契约</td></tr></tbody></table><h2 id="内部件-不导出" tabindex="-1">内部件（不导出） <a class="header-anchor" href="#内部件-不导出" aria-label="Permalink to &quot;内部件（不导出）&quot;">​</a></h2><ul><li><code>AppShell</code>：内置默认经典布局 shell（左 sidebar + 顶 header + 主体 body 1:1 镜像）——仅 AppLayout 内部 import；布局插件自供 shell（可照搬内置实现、复用上述积木）</li><li><code>AppCollapseToggle</code>：族内共享折叠积木（AppSidebar/AppAside 内部使用），未导出</li><li><code>keep-alive.ts</code>：AppBody depth-0 KeepAlive 缓存判据（真叶子 + meta.keepAlive），内部工具不入公共 barrel</li></ul><h2 id="导出面-index-ts" tabindex="-1">导出面（index.ts） <a class="header-anchor" href="#导出面-index-ts" aria-label="Permalink to &quot;导出面（index.ts）&quot;">​</a></h2><p>9 组件 + <code>export * from &quot;./types&quot;</code> + <code>./viewport</code>（<code>CORE_VIEWPORT_DECOR_ZINDEX_BELOW</code>=800 弹窗下档 / <code>CORE_VIEWPORT_DECOR_ZINDEX_ABOVE</code>=10000 弹窗上档）+ <code>./app-page-geometry</code>（<code>computeAppPageReducedViewportHeight</code>/<code>computeAppPageReducedViewportWidth</code>、<code>computeAppPageContentInset</code>、<code>computeAppPageSlotStyles</code>、<code>computeAppPageSlotShimStyles</code> + <code>APP_PAGE_SLOT_Z_INDEX</code>=1）</p><h2 id="相邻族" tabindex="-1">相邻族 <a class="header-anchor" href="#相邻族" aria-label="Permalink to &quot;相邻族&quot;">​</a></h2><ul><li><strong><code>page-layout</code></strong>（同级新族）：一整页级别的编排组件，准入标准 = <strong>DOM 根节点是 <code>AppPage</code></strong>。 列表 / 详情同页范式（<code>AppPageListDetailLayout</code> / <code>AppPageDetail</code>）已迁至该族，见 <a href="/done-coding-showcase/docs/core/src/components/page-layout/README.html"><code>../page-layout/README.md</code></a>。<code>AppPage</code> 本身留在本族——它是<strong>被</strong> 那个族使用的页面原语。</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>布局插件自供 shell 契约：<code>AppShellProps</code> / <code>AppShellSlots</code>（types.ts）</li><li>页面级骨架（ListLayout 等）以 <code>AppPage</code> 为宿主：<code>apps/reference/src/pages/app-layout/page-slots/</code></li><li>范式页：<code>apps/reference/src/App.vue</code>、<code>apps/reference/src/pages/app-layout/shell/</code>、<code>apps/reference/src/pages/app-layout/page-slots/</code>、<code>apps/reference/src/pages/app-layout/layout/</code></li></ul>',15)])])}const A=o(a,[["render",p]]);export{u as __pageData,A as default};
